package com.supersports.reviews;
import java.util.*;import java.util.concurrent.ConcurrentHashMap;import jakarta.servlet.DispatcherType;import jakarta.servlet.http.HttpServletRequest;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.security.authorization.AuthorizationDecision;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.core.*;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationProvider;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.oauth2.server.resource.authentication.JwtIssuerAuthenticationManagerResolver;import org.springframework.security.authentication.AuthenticationManagerResolver;import org.springframework.security.core.Authentication;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.security.web.access.intercept.RequestAuthorizationContext;import org.springframework.http.HttpMethod;
@Configuration(proxyBeanMethods=false) class ReviewsSecurity{
 @Bean SecurityFilterChain chain(HttpSecurity http,AuthenticationManagerResolver<HttpServletRequest> resolver)throws Exception{return http.csrf(AbstractHttpConfigurer::disable).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.dispatcherTypeMatchers(DispatcherType.ERROR).permitAll().requestMatchers("/actuator/health/liveness","/actuator/health/readiness").permitAll().requestMatchers(HttpMethod.GET,"/api/v1/reviews/products/**").permitAll().requestMatchers("/api/v1/customer/reviews/**").access((auth,ctx)->audience(auth.get(),"supersports-customer-api")).requestMatchers("/api/v1/operator/reviews/**").access((auth,ctx)->audience(auth.get(),"supersports-api")).anyRequest().denyAll()).oauth2ResourceServer(o->o.authenticationManagerResolver(resolver)).build();}
 private AuthorizationDecision audience(Authentication auth,String required){return new AuthorizationDecision(auth instanceof JwtAuthenticationToken token&&token.getToken().getAudience().contains(required));}
 @Bean AuthenticationManagerResolver<HttpServletRequest> resolver(){Set<String> issuers=Set.of("http://localhost:8180/realms/supersports","http://localhost:8180/realms/supersports-customers");Map<String,AuthenticationManager> managers=new ConcurrentHashMap<>();return new JwtIssuerAuthenticationManagerResolver(issuer->{if(!issuers.contains(issuer))return null;return managers.computeIfAbsent(issuer,this::manager);});}
 private AuthenticationManager manager(String issuer){String realm=issuer.endsWith("supersports-customers")?"supersports-customers":"supersports";String audience=realm.equals("supersports")?"supersports-api":"supersports-customer-api";NimbusJwtDecoder decoder=NimbusJwtDecoder.withJwkSetUri("http://identity:8080/realms/"+realm+"/protocol/openid-connect/certs").build();OAuth2TokenValidator<Jwt> validator=new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer(issuer),jwt->jwt.getAudience().contains(audience)?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token","Required API audience missing",null)));decoder.setJwtValidator(validator);return new JwtAuthenticationProvider(decoder)::authenticate;}
}
